int n, m;
std::cin >> n >> m;
std::vector<std::vector<int>> g(n + 1);   // 1-based
for (int i = 0; i < m; ++i) {
    int u, v;
    std::cin >> u >> v;
    g[u].push_back(v);
    g[v].push_back(u);          // 无向图要双向加边
}

std::vector<int> dist(n + 1, -1);   // -1 表示未访问
std::queue<int> q;
dist[s] = 0;
q.push(s);
while (!q.empty()) {
    int u = q.front(); q.pop();
    for (int v : g[u]) {
        if (dist[v] == -1) {          // 未访问
            dist[v] = dist[u] + 1;
            q.push(v);                // 入队时立即标记
        }
    }
}

std::vector<bool> vis(n + 1, false);
std::function<void(int)> dfs = [&](int u) {
    vis[u] = true;
    for (int v : g[u]) {
        if (!vis[v]) dfs(v);
    }
};

int blocks = 0;
for (int i = 1; i <= n; ++i) {
    if (!vis[i]) {          // 每个未访问点开一个新块
        dfs(i);
        ++blocks;
    }
}

std::vector<int> indeg(n + 1, 0);
for (int u = 1; u <= n; ++u)
    for (int v : g[u]) ++indeg[v];

std::priority_queue<int, std::vector<int>, std::greater<int>> pq;  // 小根堆 → 字典序最小
for (int i = 1; i <= n; ++i)
    if (indeg[i] == 0) pq.push(i);

std::vector<int> order;
while (!pq.empty()) {
    int u = pq.top(); pq.pop();
    order.push_back(u);
    for (int v : g[u]) {
        if (--indeg[v] == 0) pq.push(v);
    }
}
if ((int)order.size() < n) { /* 有环 */ }

struct DSU {
    std::vector<int> p, rnk;
    DSU(int n) : p(n + 1), rnk(n + 1, 0) {
        for (int i = 1; i <= n; ++i) p[i] = i;
    }
    int find(int x) {                 // 路径压缩（迭代版，防爆栈）
        int root = x;
        while (p[root] != root) root = p[root];
        while (p[x] != root) { int nx = p[x]; p[x] = root; x = nx; }
        return root;
    }
    bool unite(int a, int b) {        // 按秩合并
        a = find(a); b = find(b);
        if (a == b) return false;     // 已在同一集合（加这条边会成环）
        if (rnk[a] < rnk[b]) std::swap(a, b);
        p[b] = a;
        if (rnk[a] == rnk[b]) ++rnk[a];
        return true;
    }
    bool same(int a, int b) { return find(a) == find(b); }
};

